mapper.select:
select b.batch_id, b.paper_id, b.file_name, b.total_rows, b.success_rows, b.fail_rows, b.status, b.error_log, b.create_by, b.create_time, p.paper_name from spas_score_batch b left join spas_paper p on b.paper_id = p.paper_id
AND b.paper_id = #{paperId}
AND b.status = #{status}
AND b.file_name like concat('%', #{fileName,jdbcType=VARCHAR}, '%')
AND exists ( select 1 from spas_score_detail sd join spas_student st on st.student_id = sd.student_id left join sys_dept d on st.dept_id = d.dept_id where sd.batch_id = b.batch_id
)
order by b.batch_id desc

mapper.update:
update spas_score_batch
total_rows = #{totalRows}, success_rows = #{successRows}, fail_rows = #{failRows}, status = #{status}, error_log = #{errorLog},
where batch_id = #{batchId}

mapper.select:
select sd.detail_id, sd.paper_id, sd.question_id, sd.student_id, sd.batch_id,
       sd.score, sd.full_score, sd.rate, sd.create_time, sd.update_time,
       st.student_no, st.student_name, q.question_no
from spas_score_detail sd
left join spas_student st on sd.student_id = st.student_id
left join spas_paper_question q on sd.question_id = q.question_id


        AND sd.paper_id = #{paperId}


        AND sd.student_id = #{studentId}


        AND sd.question_id = #{questionId}


        AND sd.batch_id = #{batchId}



            AND st.dept_id in
            #{did}

        ${params.dataScope}


order by st.student_no asc, q.question_order asc

mapper.delete:
delete from spas_score_detail
where batch_id = #{batchId}
  and prev_batch_id is null
